def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+*/,:=<>-]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(formula):
        nodes = []
        operators = []
        expect_operand = True
        pending_function = None

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append(("binary", op, left, right))

        for token in token_pattern.findall(formula):
            if token in functions:
                pending_function = token
            elif token == "(":
                operators.append((pending_function, 1))
                pending_function = None
                expect_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                name, count = operators[-1]
                operators[-1] = (name, count + 1)
                expect_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                name, count = operators.pop()
                if name is not None:
                    args = nodes[-count:]
                    del nodes[-count:]
                    nodes.append(("call", name, args))
                expect_operand = False
            elif token[0].isdigit():
                nodes.append(("number", int(token)))
                expect_operand = False
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                # Prefix minus must wait for its operand.
                if op != "neg":
                    while (
                        operators
                        and isinstance(operators[-1], str)
                        and precedence[operators[-1]] >= precedence[op]
                    ):
                        reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(args):
        for node in args:
            if node[0] == "binary" and node[1] == ":":
                first = node[2][1]
                last = node[3][1]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield ("reference", name)
            else:
                yield node

    def calculate(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    done = {}
    active = set()

    for root in cells:
        if root in done:
            continue

        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in done:
                    values.append(done[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    content = cells[name].strip()
                    if not content.startswith("="):
                        value = int(content)
                        done[name] = value
                        values.append(value)
                    else:
                        active.add(name)
                        tasks.append(("finish", name))
                        tasks.append(("evaluate", parse(content[1:])))

            elif kind == "finish":
                name = task[1]
                done[name] = values[-1]
                active.remove(name)

            elif kind == "evaluate":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    values.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))
                elif node_kind == "binary":
                    tasks.append(("left_done", node[1], node[3]))
                    tasks.append(("evaluate", node[2]))
                else:
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("choose", args[1], args[2]))
                        tasks.append(("evaluate", args[0]))
                    else:
                        tasks.append((
                            "aggregate_next", name, iter(argument_nodes(args)), None
                        ))

            elif kind == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "left_done":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif kind == "right_done":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(calculate(task[1], task[2], right))

            elif kind == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append((
                        "evaluate", task[1] if condition else task[2]
                    ))

            elif kind == "aggregate_next":
                name, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    values.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append((
                        "aggregate_take", name, iterator, accumulated
                    ))
                    tasks.append(("evaluate", node))

            elif kind == "aggregate_take":
                name, iterator, accumulated = task[1:]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                if accumulated is None:
                    accumulated = value
                elif name == "SUM":
                    accumulated += value
                elif name == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                tasks.append((
                    "aggregate_next", name, iterator, accumulated
                ))

    return {name: done[name] for name in cells}
